create or replace TABLE LDL_DATA_PRODUCTION.CORE_DIM.T_FACT_INVENTORY_DIFFERENCE_BY_WAWI_ITEM cluster by (INV_DT)(
	INV_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the inventory event.',
	INV_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the subtype discriminator for inventories. It distinguishes between full and partial inventories.',
	INV_DT DATE NOT NULL COMMENT 'The date for which the inventory was done.',
	INT_ORG_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the store or warehouse, where the inventory was done.',
	INT_ORG_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the discriminators for internal organizations.',
	COUNTRY_ORG_CD VARCHAR(2) NOT NULL COMMENT 'The code of the business country for which the related country organization is responsible. (The business country is not identical to a political country.) ',
	WAWI_ITEM_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) of the Wawi item.',
	CALC_SALES_UNIT_CNT NUMBER(38,5) COMMENT 'The number of sales units (that are related to the given Wawi item) which should have been on stock in this internal organization (i.e. store or warehouse) on the inventory date. E.g. if there are two boxes with 20 sales variants each, the sales unit count is 40. For weight-based products this attribute is empty. This measure is not additive across time!',
	INV_SALES_UNIT_CNT NUMBER(38,5) COMMENT 'The number of sales units (that are related to the given Wawi item) which have actually been on stock in this internal organization (i.e. store or warehouse) on the inventory date. E.g. if there are two boxes with 20 sales variants each, the sales unit count is 40. For weight-based products this attribute is empty. This measure is not additive across time!',
	INV_DIFF_SALES_UNIT_CNT NUMBER(38,5) COMMENT 'The inventory difference, expressed as the difference in the number of sales units for this internal organization (i.e. store or warehouse) and the given Wawi item on the inventory date. E.g. if there are two boxes with 20 sales variants each, the sales unit count is 40. The inventory difference is the difference between the counted quantity and the calculated stock quantity. For weight-based products this attribute is empty.',
	CALC_QTY NUMBER(38,5) COMMENT 'The weight of the given Wawi item which should have been on stock in this internal organization (i.e. store or warehouse) on the inventory date, expressed in the indicated unit of measure. For piece-based products this measure is empty. This measure is not additive across time!',
	INV_QTY NUMBER(38,5) COMMENT 'The weight of the given Wawi item which has actually been on stock in this internal organization (i.e. store or warehouse) on the inventory date, expressed in the indicated unit of measure. For piece-based products this measure is empty. This measure is not additive across time!',
	INV_DIFF_QTY NUMBER(38,5) COMMENT 'The inventory difference, expressed as the difference in weight of the given Wawi item in this internal organization (i.e. store or warehouse) on the inventory date. The weight is expressed in the indicated unit of measure. The inventory difference is the difference between the counted quantity and the calculated stock quantity. For piece-based products this measure is empty.',
	UOM_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the unit of measure, such as kg, meter or pieces.',
	CALC_STOCK_NET_VAL NUMBER(38,5) COMMENT 'The monetary value of the given Wawi items which should have been on stock in this internal organization (i.e. store or warehouse) on the inventory date. The value is based on the net sales prices that applies to this organization and on the calculated stock quantity. This measure is not additive across time!',
	INV_NET_VAL NUMBER(38,5) COMMENT 'The monetary value of the given Wawi items which have been counted as part of the inventory process in this internal organization (i.e. store or warehouse) on the inventory date. The value is based on the net sales price that applies to this organization and and on the counted quantity. This measure is not additive across time!',
	INV_DIFF_NET_VAL NUMBER(38,5) COMMENT 'The net amount of the inventory difference for the given Wawi items , i.e. the difference between the monetary value of the calculated stock and the counted stock.',
	TURNOVER_NET_VAL NUMBER(38,5) COMMENT 'The net turnover amount in the given currency which was generated in this internal organization (i.e. store or warehouse) for the given Wawi items in the inventory period. This is the amount delivered by the cash registers. The turnover is the difference of sales and returns. (In case the internal organization references a warehouse, this is only that portion of the turnover which was generated directly in the warehouse. Turnover of stores which are managed by this warehouse, are not included.) The inventory period is the time interval between the last full inventory and this inventory.',
	CURR_CD VARCHAR(3) NOT NULL COMMENT 'The code identifying the currency according to ISO-4217.',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	constraint PK_T_FACT_INVENTORY_DIFFERENCE_BY_WAWI_ITEM primary key (INV_SID, WAWI_ITEM_SID)
)COMMENT='A transactional fact holding inventory differences on the level of Wawi items for full and partial inventories in stores and warehouses. The inventory difference is the delta between the calculated stock and the stock that has been counted.'
;